import math, json, os, sys
import numpy as np

# Physical constants (SI)
G = 6.67430e-11          # m^3 kg^-1 s^-2
c = 2.99792458e8        # m s^-1
hbar = 1.054571817e-34  # J s
k_B = 1.380649e-23      # J K^-1
M_sun = 1.98847e30      # kg


def schwarzschild_radius(M):
    return 2 * G * M / c**2

def isco_radius(M):
    # Prograde ISCO radius for a non-rotating BH (a=0) in geometric units (GM/c^2)
    return 6 * G * M / c**2

def hawking_temperature(M):
    return hbar * c**3 / (8 * math.pi * G * M * k_B)

def planck_length():
    return math.sqrt(hbar * G / c**3)

def bh_entropy(M):
    # S = k_B * 4π G M^2 / (ħ c)
    return k_B * 4 * math.pi * G * M**2 / (hbar * c)

def photon_sphere_impact_parameter(M):
    # b = 3*sqrt(3) * GM / c^2
    return 3 * math.sqrt(3) * G * M / c**2

def critical_impact_parameter(M):
    # b_crit = 2*GM/c^2 * (1 + cos(π/3)) = 2*GM/c^2 * 1.5 = 3*GM/c^2
    return 2 * G * M / c**2 * (1 + 0.5)  # 1.5 factor

def angular_size_rad(M, distance):
    # Angular size θ = 2*GM/(c^2*d)
    return 2 * G * M / (c**2 * distance)

def angular_size_arcsec(M, distance):
    rad = angular_size_rad(M, distance)
    return rad * (180 / math.pi) * 3600

def photon_sphere_impact_parameter_arcsec(M):
    b = photon_sphere_impact_parameter(M)
    # For a distant observer the angular size is b / d, but we set d=1 for impact parameter
    return b * 3600  # convert meters to arcseconds (1 m = 3600 arcsec)

def main():
    # Example: Sgr A* mass
    M = 4.31e6 * M_sun  # kg
    distance = 8.2 * 3.086e16  # 8.2 kpc in meters

    # Compute various radii and angles
    r_s = schwarzschild_radius(M)
    r_isco = isco_radius(M)
    theta_rad = angular_size_rad(M, distance)
    theta_arcsec = angular_size_arcsec(M, distance)
    b_ph = photon_sphere_impact_parameter(M)
    b_crit = critical_impact_parameter(M)
    b_crit_arcsec = photon_sphere_impact_parameter_arcsec(M)

    # Entropy
    S = bh_entropy(M)

    # Output results as JSON (for easy consumption by tests)
    result = {
        "r_s_m": r_s,
        "r_isco_m": r_isco,
        "theta_rad": theta_rad,
        "theta_arcsec": theta_arcsec,
        "b_ph_m": b_ph,
        "b_crit_m": b_crit,
        "b_crit_arcsec": b_crit_arcsec,
        "S_J": S
    }
    print(json.dumps(result, indent=2))

if __name__ == "__main__":
    main()

